using System.Text;
using System.Text.Json;
using chatai.Core.Config;
using Microsoft.Extensions.Logging;
using ntu.Sso.Enumeration;

namespace chatai.Core.Service
{
    /// <summary>
    /// flowId=8：未來教室設備支援助理。直接呼叫 Gemini generateContent（不用 file_search），
    /// 沿用跟 flowId=6/7 同一套 "Gemini" HttpClient，但 API Key（GeminiSettings:ClassroomFaqApiKey）
    /// 是獨立的一把，可單獨更換而不影響 flow=6/7。
    /// FAQ 知識量不大（約 15 類問題）且不常變動，直接把內容烘焙進 system prompt（不做完整 RAG）；
    /// 步驟圖片是預先從 Google Sheet 匯出的靜態檔案，放在 wwwroot/classroom-faq/，
    /// system prompt 裡用 markdown 圖片語法引用，前端的 marked 渲染器會自動轉成 &lt;img&gt;。
    /// 跟 flow 7 一樣靠呼叫端（RunController）把完整對話紀錄透過 history 參數傳入；
    /// 另外多支援一次性的圖片輸入（使用者附加照片問問題），只影響當次提問，不存進歷史紀錄。
    ///
    /// 身分分流（測試回饋 0811）：「老師／課程助教／學生」跟「數位學習中心人員／教室助教」看到的答案
    /// 必須嚴格分開，不能遺漏、也不能讓 AI 自行延伸內容。因此身分判斷改成在這裡（C# 端）用關鍵字比對
    /// 對話紀錄決定，而不是丟給 LLM 自己猜；判斷結果只會把「符合身分的那一種答案文字」組進 system prompt，
    /// 不符合身分的那一版文字完全不會出現在丟給模型的內容裡，結構上就不可能外洩。
    /// </summary>
    public class ClassroomFaqChatService : IClassroomFaqChatService
    {
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly AppSettingConfig _appSetting;
        private readonly ILogger<ClassroomFaqChatService> _logger;

        public ClassroomFaqChatService(
            IHttpClientFactory httpClientFactory,
            AppSettingConfig appSetting,
            ILogger<ClassroomFaqChatService> logger)
        {
            _httpClientFactory = httpClientFactory;
            _appSetting = appSetting;
            _logger = logger;
        }

        private HttpClient CreateClient()
        {
            var client = _httpClientFactory.CreateClient("Gemini");
            client.DefaultRequestHeaders.Remove("x-goog-api-key");
            client.DefaultRequestHeaders.Add("x-goog-api-key", _appSetting.ClassroomFaqGeminiApiKey);
            return client;
        }

        private enum ClassroomFaqIdentity
        {
            Unknown,
            General,
            Admin,
        }

        /// <summary>
        /// 管理者身分關鍵字，比對優先度高於一般使用者關鍵字（例如「教室助教」跟「課程助教」都含「助教」，
        /// 但兩者是不同陣營，所以用完整詞組比對，不能只比對「助教」兩個字）。
        /// </summary>
        private static readonly string[] AdminIdentityMarkers =
        {
            "數位學習中心人員", "數位學習中心", "數習中心人員", "數習中心", "教室助教",
        };

        private static readonly string[] GeneralIdentityMarkers =
        {
            "課程助教", "老師", "學生",
        };

        /// <summary>
        /// 由舊到新掃描對話紀錄＋這次提問，找使用者「第一次」明確表明的身分就鎖定、立刻回傳；
        /// 找不到就是 Unknown。刻意只認第一次宣告（通常就是開場白問完身分後的那一句回覆），
        /// 鎖定之後不再理會後面訊息裡偶然出現的關鍵字，避免對話中途無關的一句話
        /// （例如閒聊提到「我朋友是老師」）誤觸發、把已經確認的身分覆蓋掉。
        ///
        /// 使用者自己在對話裡講的身分永遠優先；只有完全沒講過的時候，才退而求其次參考
        /// SSO 帳號類型（accountTypeCode）：教師（f）／學生（u）這兩種官方帳號類型可以直接
        /// 對應到「老師／課程助教／學生」這一邊，藉此少問一次身分；至於「數位學習中心人員／
        /// 教室助教」沒有對應的 SSO 帳號類型可以判斷（職員 s 底下也可能只是一般教職員，不代表
        /// 是數習中心或教室助教），所以這一邊完全靠使用者自己在對話裡講，SSO 不會自動判定成管理者。
        ///
        /// 注意：這裡沒有辦法分辨「同一個對話串中途換了不同人在操作」（例如共用教室電腦），
        /// 一旦鎖定就會沿用到這個對話串結束為止；若要處理這種情境，需要在對話串邊界另外
        /// 設計重置機制，不是靠調整這個判斷邏輯本身能解決的。
        /// </summary>
        private static ClassroomFaqIdentity DetermineIdentity(
            IReadOnlyList<(string Role, string Text)> history,
            string question,
            string? accountTypeCode)
        {
            var userMessages = history
                .Where(h => h.Role == "user")
                .Select(h => h.Text)
                .Append(question);

            foreach (var text in userMessages)
            {
                if (AdminIdentityMarkers.Any(marker => text.Contains(marker)))
                    return ClassroomFaqIdentity.Admin;

                if (GeneralIdentityMarkers.Any(marker => text.Contains(marker)))
                    return ClassroomFaqIdentity.General;
            }

            if (accountTypeCode == AccountEnum.AccountTypeCodeEnum.Faculty ||
                accountTypeCode == AccountEnum.AccountTypeCodeEnum.Student)
                return ClassroomFaqIdentity.General;

            return ClassroomFaqIdentity.Unknown;
        }

        /// <summary>
        /// 依身分回傳對應的那一版答案文字；未知身分時完全不放任何一版的具體內容，
        /// 只放一段固定提示文字，讓模型只能照樣詢問身分，不能自己編。
        /// </summary>
        private static string Gated(ClassroomFaqIdentity identity, string generalAnswer, string adminAnswer)
        {
            return identity switch
            {
                ClassroomFaqIdentity.General => generalAnswer,
                ClassroomFaqIdentity.Admin => adminAnswer,
                _ => "（此題答案依使用者身分而定，系統目前尚未確認使用者身分。絕對不可以猜測或提供任何一種身分的具體操作步驟，請直接回覆：「請問您的身分是老師／課程助教／學生，還是數位學習中心人員／教室助教呢？」）",
            };
        }

        /// <summary>
        /// 圖片網址要用 _appSetting.BaseUrl 組成絕對網址，所以不能是編譯期常數，改成方法在請求時組出來。
        /// BaseUrl 正式環境是 https://aichat.aca.ntu.edu.tw/api/，Program.cs 已經
        /// UsePathBase("/api") + UseStaticFiles()，所以 wwwroot/classroom-faq/xxx.jpg
        /// 的絕對網址就是 {BaseUrl 去掉結尾斜線}/classroom-faq/xxx.jpg。
        /// </summary>
        private string BuildSystemInstruction(ClassroomFaqIdentity identity)
        {
            var imageBase = _appSetting.BaseUrl.TrimEnd('/') + "/classroom-faq";

            var identityStatusLine = identity switch
            {
                ClassroomFaqIdentity.General => "老師／課程助教／學生",
                ClassroomFaqIdentity.Admin => "數位學習中心人員／教室助教",
                _ => "尚未確認（使用者還沒有明確表明身分）",
            };

            var wirelessProjectionAnswer = Gated(
                identity,
                generalAnswer: """
                請向現場的教室助教反應協助處理。
                若現場沒有助教，且問題依然無法排除，請聯絡未來教室承辦人處理：
                數位學習中心 蘇怡庭小姐
                電話：3366-3367 #588
                Email：itingsu214@ntu.edu.tw
                """,
                adminAnswer: $"""
                可拿下螢幕後方偏上的 RediShow 機器，將機器電源拔掉，等 1-3 分鐘再重插。

                步驟圖（STEP 1~3 已標示在同一張圖裡）：
                ![無線投影 RediShow 拔插步驟 STEP1~3]({imageBase}/wireless-projection.jpg)
                """);

            var touchScreenCrashAnswer = Gated(
                identity,
                generalAnswer: """
                請向現場的教室助教反應協助處理。
                若現場沒有助教，且問題依然無法排除，請聯絡未來教室承辦人處理：
                數位學習中心 蘇怡庭小姐
                電話：3366-3367 #588
                Email：itingsu214@ntu.edu.tw
                """,
                adminAnswer: $"""
                可關閉螢幕後方的電源開關強制關機，並等候 3 分鐘後再重開機。

                步驟圖：
                ![從螢幕側邊往螢幕後方看會看到的開關按鈕]({imageBase}/touch-screen-power-switch.jpg)
                """);

            var teacher2SignalAnswer = Gated(
                identity,
                generalAnswer: """
                請向現場的教室助教反應協助處理。
                若現場沒有助教，且問題依然無法排除，請聯絡未來教室承辦人處理：
                數位學習中心 蘇怡庭小姐
                電話：3366-3367 #588
                Email：itingsu214@ntu.edu.tw
                """,
                adminAnswer: $"""
                重開環控沒有排除狀況的話，請到機櫃檢查矩陣的面板數字與 input 和 output 的亮燈情況，並回報給數位學習中心同仁。

                步驟圖（STEP 1~2 已標示在同一張圖裡）：
                ![機櫃矩陣面板檢查步驟 STEP1~2]({imageBase}/matrix-panel-check.jpg)
                """);

            var fanNotWorkingAnswer = Gated(
                identity,
                generalAnswer: """
                請先確定您是否已開啟環控系統。若已開啟，可能是遙控器沒電了，可在門口進來右手邊第一排抽屜最下方找電池做替換喔。
                若您是學生，請找教室助教或課程助教協助。
                """,
                adminAnswer: "請先確定您是否已開啟環控系統。若已開啟，可能是遙控器沒電了，可在門口進來右手邊第一排抽屜最下方找電池做替換喔。");

            var monitorNoSignalAnswer = Gated(
                identity,
                generalAnswer: """
                請先檢查是否有開啟電源，如已開啟電源但無畫面，請通知數習中心報修。
                （監控螢幕若沒有顯示畫面，就代表導播機沒有接收到訊號，也就不會送去給電腦的相機或視訊軟體）
                """,
                adminAnswer: $"""
                可先檢查導播機監看螢幕的兩條線是否有確實接上。若有接上，但還是沒有畫面，可以嘗試電源線拔掉重插。

                步驟圖：
                ![導播機監看螢幕線材檢查位置]({imageBase}/director-monitor-cables.jpg)
                """);

            var cameraZoomAnswer = Gated(
                identity,
                generalAnswer: $"""
                可至講桌右手邊抽屜的遙控器調整 Zoom In 或 Zoom Out。如果要調整教室後方攝影機請先按數字「1」再操作；如果要調整講桌後方攝影機請先按數字「2」再操作。
                若您是學生，請找教室助教或課程助教協助。

                步驟圖（STEP 1~3 已標示在同一張圖裡）：
                ![錄播攝影機 Zoom 遙控器步驟 STEP1~3]({imageBase}/camera-zoom.jpg)
                """,
                adminAnswer: $"""
                可至講桌右手邊抽屜的遙控器調整 Zoom In 或 Zoom Out。如果要調整教室後方攝影機請先按數字「1」再操作；如果要調整講桌後方攝影機請先按數字「2」再操作。

                步驟圖（STEP 1~3 已標示在同一張圖裡）：
                ![錄播攝影機 Zoom 遙控器步驟 STEP1~3]({imageBase}/camera-zoom.jpg)
                """);

            return $$"""
# Role

你是臺大「未來教室」設備支援助理，服務對象包含在未來教室使用設備時遇到問題的老師、課程助教、學生，以及負責維護教室的數位學習中心人員與教室助教。

預設請使用繁體中文回覆，語氣像熟悉現場設備、有耐心的技術支援人員；只有當使用者的提問全為英文，或明確要求以英文回覆時，才改用英文回答，其餘情況一律使用繁體中文。

---

# 身分辨識

使用者進入對話時，畫面上已經顯示以下開場白（由前端固定顯示，會被算成對話歷史裡的第一則助理訊息，不需要你重複輸出）：

「您好！歡迎使用未來教室 AI 助手 👋
無論是設備操作、教室使用或其他相關問題，都可以問我。
為了提供更精準的協助，請先選擇您的身分：老師／課程助教／學生　｜　數位學習中心人員／教室助教」

系統已經自動判斷使用者身分（依對話紀錄裡使用者自己講過的話、或校內帳號資訊判斷，不是靠你自己猜），目前判斷結果如下：

**使用者身分：{{identityStatusLine}}**

規則：
1. 下方 FAQ 中標示「（依身分分流）」的問題，只會列出符合上述判斷結果的那一種答案內容；如果判斷結果是「尚未確認」，這些題目底下只會有一段固定提示文字，請照該提示文字直接詢問使用者身分，絕對不可以自己猜測或編造任何一種身分的具體操作步驟。
2. 上面的身分判斷結果是系統依對話紀錄自動判斷出來的最終依據，不需要你自己重新從對話紀錄猜測身分，也不要質疑、修改或覆蓋這個判斷結果。
3. 提問不屬於「（依身分分流）」項目時，不受身分影響，可直接回答。

---

# 範圍限制

你只回答跟未來教室介紹、設備、操作有關的問題（例如教室簡介與申請、無線投影、環控系統、螢幕與觸控螢幕、電子白板、電燈、教室通風與電扇、播放檔案、麥克風、桌子與白板使用、充電、遠距教學、錄播與攝影機等）。

如果使用者問的是跟未來教室設備無關的問題（例如課業、選課、生涯規劃、行政流程等），請明確告知這不在你的服務範圍內，並引導使用者回到設備相關的問題，不要嘗試回答。

如果使用者表示「這堂課不適合用未來教室」或「不需要用未來教室」，這屬於課程安排問題，請引導使用者向授課老師或課堂助教反應；只有教室設備本身的操作建議，才適合透過下方的問題回報表單提供。

---

# 對話風格

1. 使用者描述問題模糊時，先反問釐清細節，不要急著丟一串步驟。例如使用者只說「沒辦法連上教室 WiFi」，你可以問「請問是連不上哪一個名稱的 WiFi 呢？」「其他同學的裝置也連不上嗎？」等，引導找出真正的問題點，再給出解法。
2. 你要能理解使用者用不同說法描述同一個問題（換句話說也能聽懂），不要因為用詞跟下面的 FAQ 不完全一樣就答不出來。
3. 使用者可以在同一個情境下持續追問，不需要每次都重新描述問題一次；請根據對話紀錄判斷目前討論的是哪個設備、進行到哪個排除步驟。
4. 如果使用者操作後問題仍未排除，或明確表示還是沒辦法解決，才進入「無法解決時的處理方式」。

---

# 輸出格式

1. 說明操作步驟時，用條列式 SOP（1. 2. 3. ...），一步一個動作。
2. 需要表達流程順序時，用文字箭頭表示（例如「1. 檢查電源 → 2. 確認開關位置 → 3. 重新開機」），不要嘗試畫真正的流程圖。
3. 如果這個問題有對應的步驟圖片（見下方 FAQ），請在對應的步驟文字後面，用 markdown 圖片語法附上圖片，例如：`![說明文字]({{imageBase}}/檔名.jpg)`，讓圖片直接顯示在對話中，不要只給連結。

